CREATE TABLE live_authority_epochs(id TEXT PRIMARY KEY,community_id TEXT NOT NULL,event_id TEXT NOT NULL,device_installation_id TEXT NOT NULL,epoch INTEGER NOT NULL CHECK(epoch>0),state TEXT NOT NULL CHECK(state IN('confirmed','revoked')),confirmed_at TEXT NOT NULL,UNIQUE(event_id,epoch)) STRICT;
CREATE UNIQUE INDEX one_confirmed_live_authority ON live_authority_epochs(event_id) WHERE state='confirmed';
CREATE TABLE live_queue_entries(id TEXT PRIMARY KEY,community_id TEXT NOT NULL,event_id TEXT NOT NULL,song_id TEXT NOT NULL,state TEXT NOT NULL CHECK(state IN('suggested','planned','queued','current','performed','skipped','deferred','restored')),revision INTEGER NOT NULL CHECK(revision>0),audience_visible INTEGER NOT NULL CHECK(audience_visible IN(0,1)),created_at TEXT NOT NULL,updated_at TEXT NOT NULL) STRICT;
CREATE TABLE performance_history(id TEXT PRIMARY KEY,event_id TEXT NOT NULL,entry_id TEXT NOT NULL,song_id TEXT NOT NULL,performed_at TEXT NOT NULL,authority_epoch INTEGER NOT NULL,revision INTEGER NOT NULL,FOREIGN KEY(entry_id) REFERENCES live_queue_entries(id)) STRICT;
CREATE TABLE live_operation_receipts(event_id TEXT NOT NULL,operation_id TEXT NOT NULL,command_hash TEXT NOT NULL,result_json TEXT NOT NULL,audit_event_id TEXT NOT NULL,created_at TEXT NOT NULL,PRIMARY KEY(event_id,operation_id)) STRICT;
